def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    pressure_bids = []
    cindy_bid = None
    eric_bid = None
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid')
            prev_bids.append(bid)
            pressure_bids.append(bid)
            if oid == 'Cindy':
                cindy_bid = bid
            if oid == 'Eric':
                eric_bid = bid

    highest_prev = max(prev_bids) if prev_bids else 0.0
    realistic_prev = 0.0
    if pressure_bids:
        filtered = [b for b in pressure_bids if b <= DAILY_SALARY * 2.2]
        realistic_prev = max(filtered) if filtered else min(highest_prev, DAILY_SALARY * 1.6)

    scarcity = supply <= 17
    abundant = supply >= 22
    critical = hp <= 3 or no_water_days >= 2
    fragile = hp <= 5 or no_water_days >= 1

    base = DAILY_SALARY * 0.42
    if abundant:
        base = DAILY_SALARY * 0.28
    elif scarcity:
        base = DAILY_SALARY * 0.72

    if realistic_prev > 0:
        if critical:
            target = max(base, realistic_prev + 3.0)
        elif fragile:
            target = max(base, realistic_prev + 1.5)
        else:
            if realistic_prev >= DAILY_SALARY * 1.4:
                target = DAILY_SALARY * 0.38 if abundant else DAILY_SALARY * 0.52
            else:
                target = max(base, realistic_prev + 1.0)
    else:
        target = base

    if cindy_bid is not None and cindy_bid >= 180 and not critical:
        target = min(target, DAILY_SALARY * 0.6 if not scarcity else DAILY_SALARY * 0.82)

    if eric_bid is not None and scarcity:
        target = max(target, min(eric_bid + 2.0, DAILY_SALARY * 1.35))

    if day >= 8:
        if hp >= 7 and no_water_days == 0 and not scarcity:
            target *= 0.9
        elif fragile:
            target *= 1.08

    if critical:
        target = max(target, DAILY_SALARY * 0.88)

    target = max(0.0, min(target, budget))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, just bid enough to secure water
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    # Read yesterday's immediate bidding pressure
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_highest = sorted_bids[1]

    my_hp = my_status['hp']
    my_budget = my_status['budget']

    # Estimate how many water units likely exist today
    # (used only to scale risk; indices are not used)
    # supply is float; compute units as float then use thresholds.
    units = supply / float(WATER_REQ)

    # Base aggressiveness: if our HP is healthy, undercut; if low, match pressure.
    # Thresholds derived from yesterday: Alex ~143, Cindy ~191, Eric ~110.
    extreme_pressure = highest_prev_bid >= DAILY_SALARY * 1.6  # >=144
    high_pressure = highest_prev_bid >= DAILY_SALARY * 1.1     # >=99

    # Choose target bid near but not equal to prior highest to win at lower cost.
    # If extreme pressure and our HP is low, we must bid closer to highest.
    if extreme_pressure:
        if my_hp <= 2:
            target = highest_prev_bid * 0.98
        else:
            target = max(second_highest + 2.0, highest_prev_bid * 0.92)
    elif high_pressure:
        if my_hp <= 2:
            target = highest_prev_bid * 0.95
        else:
            target = max(second_highest + 1.5, highest_prev_bid * 0.88)
    else:
        # Lower pressure: bid moderate to secure without wasting budget.
        # If supply is tight (few units), increase slightly.
        tight_supply = units <= 2.0
        if tight_supply:
            target = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.85)
        else:
            target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.75)

    # Budget and HP safety caps
    # If no-water days high, we should bid more.
    no_water_days = my_status.get('no_water_days', 0)
    pressure_from_deficit = 0.0
    if no_water_days >= 2:
        pressure_from_deficit = DAILY_SALARY * 0.35
    if no_water_days >= 3:
        pressure_from_deficit = DAILY_SALARY * 0.55

    target += pressure_from_deficit

    # Final clamp: never exceed budget; also avoid bidding beyond a reasonable fraction when HP is good.
    if my_hp >= 6:
        cap = my_budget * 0.55
    elif my_hp >= 3:
        cap = my_budget * 0.75
    else:
        cap = my_budget * 0.95

    bid = min(my_budget, target, cap)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0

    if supply < 18.0:
        bid = min(my_status['budget'], avg_opp_bid * 1.1)
    elif supply > 22.0:
        bid = min(my_status['budget'], avg_opp_bid * 0.6)
    else:
        bid = min(my_status['budget'], avg_opp_bid * 0.9)

    if my_status['hp'] < 3:
        bid = min(my_status['budget'], max(bid, 120.0))

    return float(max(0.0, bid))
